import { useState, useCallback, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useI18n } from '../i18n/I18nContext';
import { useStitchedData } from '../hooks/useDataFetch';
import LoadingSpinner from '../components/LoadingSpinner';
import { PageHeader } from '../components/ui';
import PricesTable from '../components/prices/PricesTable';
import { DetailModal } from '../components/prices/PricesDetail';

const API_BASE = globalThis.process?.env?.VITE_API_BASE || '';

async function fetchWithAuth(url, options = {}) {
  const res = await fetch(`${API_BASE}${url}`, {
    ...options,
    credentials: 'include',
    headers: { 'Content-Type': 'application/json', ...options.headers },
  });
  if (res.status === 401) {
    try {
      const refreshRes = await fetch(`${API_BASE}/api/auth/refresh`, { method: 'POST', credentials: 'include' });
      if (refreshRes.ok) {
        return fetch(`${API_BASE}${url}`, {
          ...options,
          credentials: 'include',
          headers: { 'Content-Type': 'application/json', ...options.headers },
        });
      }
    } catch {}
    throw new Error('SESSION_EXPIRED');
  }
  return res;
}

async function fetchCSRF() {
  const res = await fetch(`${API_BASE}/api/csrf-token`, { credentials: 'include' });
  const data = await res.json();
  return data.csrfToken;
}

export default function Prices() {
  const { t, lang } = useI18n();
  const navigate = useNavigate();
  const { data: allData, loading } = useStitchedData();

  const [zoneFilter, setZoneFilter] = useState('all');
  const [catFilter, setCatFilter] = useState('all');
  const [search, setSearch] = useState('');
  const [sortBy, setSortBy] = useState('price-asc');
  const [priceMin, setPriceMin] = useState('');
  const [priceMax, setPriceMax] = useState('');
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState(null);
  const [editMode, setEditMode] = useState(false);
  const [rows, setRows] = useState([]);
  const [initialized, setInitialized] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [editForm, setEditForm] = useState({});
  const [toast, setToast] = useState(null);
  const [deleteId, setDeleteId] = useState(null);

  useEffect(() => {
    if (!allData.length) return;
    const merged = allData.map((pz) => ({
      priceId: pz.priceId || null,
      pizzeriaId: pz.id,
      name: pz.name,
      cityName: pz.cityName,
      category: pz.category,
      margheritaPrice: pz.margheritaPrice || 0,
      currency: pz.currency || 'EUR',
      lastUpdated: pz.lastUpdated || new Date().toISOString(),
      source: pz.priceSource || 'unverified',
    }));
    setRows(merged);
    setInitialized(true);
  }, [allData]);

  useEffect(() => {
    if (editMode && !initialized) return;
    if (!editMode) { setEditingId(null); setEditForm({}); }
  }, [editMode, initialized]);

  const data = editMode && initialized ? rows : allData;

  const cities = useMemo(() => ['all', ...new Set(data.map((d) => d.cityName))], [data]);
  const categories = useMemo(() => ['all', ...new Set(data.map((d) => d.category))], [data]);

  const filtered = useMemo(() => {
    return data.filter((p) => {
      const matchZone = zoneFilter === 'all' || p.cityName === zoneFilter;
      const matchCat = catFilter === 'all' || p.category === catFilter;
      const matchSearch = search === '' || p.name.toLowerCase().includes(search.toLowerCase()) || p.cityName.toLowerCase().includes(search.toLowerCase());
      const matchPriceMin = priceMin === '' || p.margheritaPrice >= parseFloat(priceMin);
      const matchPriceMax = priceMax === '' || p.margheritaPrice <= parseFloat(priceMax);
      return matchZone && matchCat && matchSearch && matchPriceMin && matchPriceMax;
    });
  }, [data, zoneFilter, catFilter, search, priceMin, priceMax]);

  const sorted = useMemo(() => {
    return [...filtered].sort((a, b) => {
      switch (sortBy) {
        case 'price-asc': return a.margheritaPrice - b.margheritaPrice;
        case 'price-desc': return b.margheritaPrice - a.margheritaPrice;
        case 'name-asc': return a.name.localeCompare(b.name);
        case 'rating-desc': return b.rating - a.rating;
        default: return 0;
      }
    });
  }, [filtered, sortBy]);

  const stats = useMemo(() => {
    const prices = sorted.map((p) => p.margheritaPrice || 0);
    const globalPrices = allData.map((p) => p.margheritaPrice || 0);
    const min = prices.length > 0 ? Math.min(...prices) : 0;
    const max = prices.length > 0 ? Math.max(...prices) : 0;
    const avg = prices.length > 0 ? prices.reduce((s, p) => s + p, 0) / prices.length : 0;
    const sortedPrices = [...prices].sort((a, b) => a - b);
    const median = sortedPrices.length > 0 ? sortedPrices[Math.floor(sortedPrices.length / 2)] : 0;
    const range = max - min;
    const globalAvg = globalPrices.length > 0 ? globalPrices.reduce((s, p) => s + p, 0) / globalPrices.length : 0;
    return { min, max, avg, median, range, globalAvg };
  }, [sorted, allData]);

  const cheapest = sorted.length > 0 ? sorted.find((p) => p.margheritaPrice === stats.min) : null;
  const priciest = sorted.length > 0 ? sorted.find((p) => p.margheritaPrice === stats.max) : null;

  const showToast = useCallback((msg, isError = false) => {
    setToast({ msg, isError });
    setTimeout(() => setToast(null), 3000);
  }, []);

  const exportCSV = () => {
    const header = 'Name,City,Category,Price,Rating\n';
    const csvRows = sorted.map((p) => `"${p.name}","${p.cityName}","${p.category}",${p.margheritaPrice},${p.rating}`).join('\n');
    const blob = new Blob([header + csvRows], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'pizza-peninsula-prices.csv';
    a.click();
    URL.revokeObjectURL(url);
  };

  const startEdit = (row) => {
    setEditingId(row.pizzeriaId);
    setEditForm({
      margheritaPrice: row.margheritaPrice,
      currency: row.currency,
      source: row.source,
      lastUpdated: row.lastUpdated,
    });
  };

  const cancelEdit = () => { setEditingId(null); setEditForm({}); };

  const saveEdit = async () => {
    const price = parseFloat(editForm.margheritaPrice);
    if (isNaN(price) || price < 0 || price > 100) {
      showToast(t('admin.toastInvalidPrice'), true);
      return;
    }

    try {
      const csrfToken = await fetchCSRF();
      const res = await fetchWithAuth(`${API_BASE}/api/prices/${editingId}`, {
        method: 'PUT',
        headers: { 'X-CSRF-Token': csrfToken },
        body: JSON.stringify({ ...editForm, margheritaPrice: price }),
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error || t('common.saveError'));
      }

      setRows((prev) =>
        prev.map((r) =>
          r.pizzeriaId === editingId ? { ...r, ...editForm, margheritaPrice: price, lastUpdated: new Date().toISOString() } : r
        )
      );
      setEditingId(null);
      setEditForm({});
      showToast(t('admin.toastRowUpdated'));
    } catch (err) {
      if (err.message === 'SESSION_EXPIRED') {
        navigate('/login');
        return;
      }
      showToast(err.message, true);
    }
  };

  const deletePrice = async (pizzeriaId) => {
    try {
      const csrfToken = await fetchCSRF();
      const res = await fetchWithAuth(`${API_BASE}/api/prices/${pizzeriaId}`, {
        method: 'DELETE',
        headers: { 'X-CSRF-Token': csrfToken },
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error || t('common.error'));
      }

      setRows((prev) => prev.filter((r) => r.pizzeriaId !== pizzeriaId));
      setDeleteId(null);
      showToast(t('admin.toastRowDeleted'));
    } catch (err) {
      if (err.message === 'SESSION_EXPIRED') {
        navigate('/login');
        return;
      }
      showToast(err.message, true);
    }
  };

  const exportJSON = () => {
    const json = rows.map((r) => ({
      id: r.priceId || `pr-new-${r.pizzeriaId}`,
      pizzeriaId: r.pizzeriaId,
      margheritaPrice: r.margheritaPrice,
      currency: r.currency,
      lastUpdated: r.lastUpdated,
      source: r.source,
    }));
    const blob = new Blob([JSON.stringify(json, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'prices.json';
    a.click();
    URL.revokeObjectURL(url);
    showToast(t('admin.toastExported'));
  };

  if (loading) return <LoadingSpinner fullScreen />;

  return (
    <div className="p-6 md:p-12">
      {toast && (
        <div className={`fixed top-4 right-4 z-[100] font-headline font-bold uppercase px-6 py-3 border-4 border-primary shadow-[4px_4px_0px_0px_rgba(26,26,26,1)] ${toast.isError ? 'bg-secondary text-on-tertiary' : 'bg-primary text-on-primary'}`}>
          {toast.msg}
        </div>
      )}

      <PageHeader title={t('prices.title')} subtitle={t('prices.subtitle')}>
        <div className="flex items-center gap-3">
          {editMode && (
            <>
              <button onClick={exportJSON} className="flex items-center gap-2 bg-surface text-primary font-headline font-bold uppercase py-2 px-4 border-2 border-primary shadow-[2px_2px_0px_0px_rgba(26,26,26,1)] hover:bg-primary hover:text-on-primary transition-colors text-sm">
                <span className="material-symbols-outlined text-sm">download</span>
                {t('admin.exportJSON')}
              </button>
            </>
          )}
          <button
            onClick={exportCSV}
            className="flex items-center gap-2 bg-background text-primary font-headline font-bold uppercase py-3 px-6 border-4 border-primary shadow-[4px_4px_0px_0px_rgba(26,26,26,1)] hover:bg-primary hover:text-on-primary transition-colors"
          >
            <span className="material-symbols-outlined">download</span>
            {t('prices.exportCSV')}
          </button>
          <button
            onClick={() => setEditMode((v) => !v)}
            className={`flex items-center gap-2 font-headline font-bold uppercase py-3 px-6 border-4 border-primary shadow-[4px_4px_0px_0px_rgba(26,26,26,1)] transition-colors ${
              editMode ? 'bg-tertiary text-on-tertiary hover:bg-primary hover:text-on-primary' : 'bg-primary text-on-primary hover:bg-secondary'
            }`}
          >
            <span className="material-symbols-outlined">{editMode ? 'visibility' : 'edit'}</span>
            {editMode ? t('common.view') : t('common.edit')}
          </button>
        </div>
      </PageHeader>

      <div className="flex items-center gap-4 mb-6">
        <span className="font-headline font-bold uppercase text-sm bg-secondary text-on-secondary px-3 py-1 border-2 border-primary">
          {allData.length} {allData.length === 1 ? t('prices.pizzeriaSingular') : t('prices.pizzeriaPlural')}
        </span>
        <span className="font-headline font-bold uppercase text-sm text-on-surface-variant">
          {cities.length - 1} {t('nav.network')}
        </span>
        <span className="font-headline font-bold uppercase text-sm bg-tertiary text-on-tertiary px-3 py-1 border-2 border-primary">
          {filtered.length} {t('common.filter').toLowerCase()}
        </span>
        {editMode && (
          <span className="font-headline font-bold uppercase text-sm bg-primary-container text-primary px-3 py-1 border-2 border-primary">
            {t('prices.editModeBadge')}
          </span>
        )}
      </div>

      <section className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
        <div className="bg-surface-variant border-4 border-primary p-4 shadow-[4px_4px_0px_0px_rgba(26,26,26,1)]">
          <label className="block text-xs font-black font-headline uppercase tracking-widest mb-2 text-primary">
            {t('prices.zoneFilter')}
          </label>
          <select
            className="w-full bg-background border-2 border-primary p-2 font-body font-bold text-primary focus:ring-0 focus:border-secondary cursor-pointer"
            value={zoneFilter}
            onChange={(e) => { setZoneFilter(e.target.value); setPage(0); }}
          >
            {cities.map((c) => (
              <option key={c} value={c}>{c === 'all' ? t('prices.allZones') : c}</option>
            ))}
          </select>
        </div>
        <div className="bg-surface-variant border-4 border-primary p-4 shadow-[4px_4px_0px_0px_rgba(26,26,26,1)]">
          <label className="block text-xs font-black font-headline uppercase tracking-widest mb-2 text-primary">
            {t('prices.category')}
          </label>
          <select
            className="w-full bg-background border-2 border-primary p-2 font-body font-bold text-primary focus:ring-0 focus:border-secondary cursor-pointer"
            value={catFilter}
            onChange={(e) => { setCatFilter(e.target.value); setPage(0); }}
          >
            {categories.map((c) => (
              <option key={c} value={c}>{c === 'all' ? t('prices.allCategories') : t(`common.${c === 'wood-fired' ? 'woodFired' : c}`)}</option>
            ))}
          </select>
        </div>
        <div className="bg-primary-container border-4 border-primary p-4 shadow-[4px_4px_0px_0px_rgba(26,26,26,1)] flex items-center justify-between">
          <div>
            <div className="text-xs font-black font-headline uppercase tracking-widest mb-1 text-primary">{t('prices.avgPrice')}</div>
            <div className="text-3xl font-black font-headline text-primary">&euro;{stats.avg.toFixed(2)}</div>
          </div>
          <span className="material-symbols-outlined text-4xl text-primary">trending_up</span>
        </div>
        <div className="bg-surface-variant border-4 border-primary p-4 shadow-[4px_4px_0px_0px_rgba(26,26,26,1)] flex items-center justify-between">
          <div>
            <div className="text-xs font-black font-headline uppercase tracking-widest mb-1 text-primary">{t('prices.medianTitle')}</div>
            <div className="text-3xl font-black font-headline text-primary">&euro;{stats.median.toFixed(2)}</div>
          </div>
          <span className="material-symbols-outlined text-4xl text-primary">balance</span>
        </div>
      </section>

      <section className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
        <div>
          <label className="block text-xs font-black font-headline uppercase tracking-widest mb-1 text-primary">{t('prices.priceRange')}</label>
          <div className="flex gap-2">
            <input
              className="w-full bg-surface border-2 border-primary py-2 px-3 font-body focus:outline-none focus:border-secondary"
              placeholder={t('prices.from')}
              type="number"
              min="0"
              step="0.5"
              value={priceMin}
              onChange={(e) => { setPriceMin(e.target.value); setPage(0); }}
            />
            <input
              className="w-full bg-surface border-2 border-primary py-2 px-3 font-body focus:outline-none focus:border-secondary"
              placeholder={t('prices.to')}
              type="number"
              min="0"
              step="0.5"
              value={priceMax}
              onChange={(e) => { setPriceMax(e.target.value); setPage(0); }}
            />
          </div>
        </div>
        <div>
          <label className="block text-xs font-black font-headline uppercase tracking-widest mb-1 text-primary">{t('prices.sortBy')}</label>
          <select
            className="w-full bg-background border-2 border-primary p-2 font-body font-bold text-primary focus:ring-0 focus:border-secondary cursor-pointer"
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value)}
          >
            <option value="price-asc">{t('prices.sortPriceAsc')}</option>
            <option value="price-desc">{t('prices.sortPriceDesc')}</option>
            <option value="name-asc">{t('prices.sortNameAsc')}</option>
            <option value="rating-desc">{t('prices.sortRatingDesc')}</option>
          </select>
        </div>
      </section>

      {sorted.length > 0 && (
        <section className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
          {cheapest && (
            <div className="bg-tertiary-container border-4 border-tertiary p-4 shadow-[4px_4px_0px_0px_rgba(26,26,26,1)]">
              <div className="flex items-center gap-2 mb-1">
                <span className="material-symbols-outlined text-tertiary" style={{ fontVariationSettings: "'FILL' 1" }}>trending_down</span>
                <span className="text-xs font-black font-headline uppercase tracking-widest text-tertiary">{t('prices.cheapestTitle')}</span>
              </div>
              <p className="font-headline font-black text-lg text-tertiary">{cheapest.name}</p>
              <p className="font-headline font-bold text-2xl text-tertiary">&euro;{cheapest.margheritaPrice?.toFixed(2)}</p>
              <p className="text-xs font-label text-tertiary/70 uppercase">{cheapest.cityName}</p>
            </div>
          )}
          <div className="bg-primary-container border-4 border-primary p-4 shadow-[4px_4px_0px_0px_rgba(26,26,26,1)]">
            <div className="flex items-center gap-2 mb-1">
              <span className="material-symbols-outlined text-primary" style={{ fontVariationSettings: "'FILL' 1" }}>balance</span>
              <span className="text-xs font-black font-headline uppercase tracking-widest text-primary">{t('prices.rangeTitle')}</span>
            </div>
            <p className="font-headline font-bold text-2xl text-primary">&euro;{stats.min.toFixed(2)} - &euro;{stats.max.toFixed(2)}</p>
            <p className="text-xs font-label text-primary/70 uppercase">{t('prices.minPrice')}: &euro;{stats.min.toFixed(2)} &middot; {t('prices.maxPrice')}: &euro;{stats.max.toFixed(2)}</p>
          </div>
          {priciest && (
            <div className="bg-secondary-container border-4 border-secondary p-4 shadow-[4px_4px_0px_0px_rgba(26,26,26,1)]">
              <div className="flex items-center gap-2 mb-1">
                <span className="material-symbols-outlined text-secondary" style={{ fontVariationSettings: "'FILL' 1" }}>trending_up</span>
                <span className="text-xs font-black font-headline uppercase tracking-widest text-secondary">{t('prices.priciestTitle')}</span>
              </div>
              <p className="font-headline font-black text-lg text-secondary">{priciest.name}</p>
              <p className="font-headline font-bold text-2xl text-secondary">&euro;{priciest.margheritaPrice?.toFixed(2)}</p>
              <p className="text-xs font-label text-secondary/70 uppercase">{priciest.cityName}</p>
            </div>
          )}
        </section>
      )}

      <PricesTable
        sorted={sorted} stats={stats} page={page} setPage={setPage}
        editingId={editingId} editForm={editForm} setEditForm={setEditForm}
        onStartEdit={startEdit} onSaveEdit={saveEdit} onCancelEdit={cancelEdit}
        onDelete={setDeleteId}
        editMode={editMode}
        setSelected={setSelected}
        t={t}
      />

      {deleteId && (
        <div className="fixed inset-0 bg-black/50 z-[200] flex items-center justify-center p-4">
          <div className="bg-surface border-4 border-primary shadow-[8px_8px_0px_0px_rgba(26,26,26,1)] w-full max-w-md">
            <div className="p-6">
              <h2 className="text-xl font-headline font-black uppercase text-primary mb-4">
                {t('prices.deleteConfirmPrice', { name: rows.find(r => r.pizzeriaId === deleteId)?.name })}
              </h2>
              <div className="flex gap-3 justify-end">
                <button onClick={() => setDeleteId(null)} className="bg-surface text-primary font-headline font-bold uppercase py-3 px-6 border-2 border-primary shadow-[2px_2px_0px_0px_rgba(26,26,26,1)] hover:bg-error-container transition-colors text-sm">{t('admin.cancel')}</button>
                <button onClick={() => deletePrice(deleteId)} className="bg-secondary text-on-tertiary font-headline font-bold uppercase py-3 px-6 border-2 border-primary shadow-[2px_2px_0px_0px_rgba(26,26,26,1)] hover:bg-error-container transition-colors text-sm">{t('common.delete')}</button>
              </div>
            </div>
          </div>
        </div>
      )}

      <DetailModal selected={selected} setSelected={setSelected} stats={stats} t={t} lang={lang} />
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useI18n } from '../i18n/I18nContext';
import { useTheme } from '../theme/ThemeContext';

const ZONES = [
  'Massa Lubrense',
  'Sorrento',
  "Sant'Agnello",
  'Piano di Sorrento',
  'Meta',
  'Vico Equense',
];

function Toggle({ value, onChange }) {
  return (
    <button
      onClick={() => onChange(!value)}
      className={`w-14 h-8 border-2 border-primary flex items-center transition-colors ${value ? 'bg-primary justify-end' : 'bg-surface justify-start'}`}
    >
      <div className="w-6 h-6 bg-on-primary border-2 border-primary shadow-[2px_2px_0px_0px_rgba(26,26,26,1)] mx-1" />
    </button>
  );
}

function TwoFAModal({ onClose, onEnabled }) {
  const [step, setStep] = useState('setup');
  const [qrCode, setQrCode] = useState(null);
  const [secret, setSecret] = useState('');
  const [verifyCode, setVerifyCode] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSetup = async () => {
    setLoading(true);
    setError('');
    try {
      const csrfRes = await fetch('/api/csrf-token', { credentials: 'include' });
      const { csrfToken } = await csrfRes.json();

      const res = await fetch('/api/auth/2fa/setup', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || t('settings.saveError'));

      setQrCode(data.qrCode);
      setSecret(data.secret);
      setStep('setup');
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleVerify = async () => {
    setLoading(true);
    setError('');
    try {
      const csrfRes = await fetch('/api/csrf-token', { credentials: 'include' });
      const { csrfToken } = await csrfRes.json();

      const res = await fetch('/api/auth/2fa/verify-setup', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
        body: JSON.stringify({ code: verifyCode }),
      });
      const data = await res.json();
      if (!res.ok) {
        const serverErrors = {
          'Codice non valido': t('login.invalidCode'),
          'Nessun setup in corso': t('login.invalidCode'),
          'Codice mancante': t('login.invalidCode'),
        };
        throw new Error(serverErrors[data.error] || data.error || t('login.invalidCode'));
      }

      onEnabled();
      onClose();
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 overflow-y-auto">
      <div className="bg-surface border-4 border-primary shadow-[8px_8px_0px_0px_rgba(26,26,26,1)] w-full max-w-md my-8">
        <div className="bg-primary text-on-primary p-4 border-b-4 border-primary flex justify-between items-center">
          <h3 className="font-headline font-black text-lg uppercase">
            {step === 'setup' ? t('settings.enable2FA') : t('settings.verify2FA')}
          </h3>
          <button onClick={onClose} className="text-on-primary hover:opacity-75">
            <span className="material-symbols-outlined">close</span>
          </button>
        </div>

        <div className="p-6 space-y-4">
          {error && (
            <div className="bg-error-container border-2 border-error p-3 font-label font-bold uppercase text-sm text-error">
              {error}
            </div>
          )}

          {step === 'setup' && (
            <>
              <p className="font-body text-sm text-on-surface-variant">
                {t('settings.qrDesc')}
              </p>
              <button
                onClick={handleSetup}
                disabled={loading}
                className="w-full bg-primary text-on-primary font-headline font-bold uppercase py-3 border-2 border-primary shadow-[4px_4px_0px_0px_rgba(26,26,26,1)] hover:bg-secondary hover:border-secondary transition-colors disabled:opacity-50"
              >
                {loading ? t('settings.generating') : t('settings.generateQR')}
              </button>
              {qrCode && (
                <>
                  <div className="flex justify-center">
                    <img src={qrCode} alt="QR Code 2FA" className="border-2 border-primary p-2 bg-white" />
                  </div>
                  <div className="bg-background border-2 border-primary p-3">
                    <label className="block text-xs font-black font-headline uppercase tracking-widest mb-1 text-primary">
                      {t('settings.manualKey')}
                    </label>
                    <code className="font-mono text-sm break-all text-primary">{secret}</code>
                  </div>
                  <button
                    onClick={() => setStep('verify')}
                    className="w-full bg-secondary text-on-error font-headline font-bold uppercase py-3 border-2 border-primary shadow-[4px_4px_0px_0px_rgba(26,26,26,1)] hover:bg-primary hover:text-on-primary transition-colors"
                  >
                    {t('settings.next')}
                  </button>
                </>
              )}
            </>
          )}

          {step === 'verify' && (
            <>
              <p className="font-body text-sm text-on-surface-variant">
                {t('settings.verifyCodeDesc')}
              </p>
              <input
                type="text"
                inputMode="numeric"
                pattern="[0-9]{6}"
                maxLength={6}
                value={verifyCode}
                onChange={(e) => setVerifyCode(e.target.value.replace(/\D/g, ''))}
                className="w-full bg-background border-2 border-primary p-3 font-body font-bold text-primary text-center text-2xl tracking-widest focus:outline-none focus:border-secondary"
                placeholder={t('settings.verifyCodePlaceholder')}
                autoFocus
              />
              <button
                onClick={handleVerify}
                disabled={loading || verifyCode.length !== 6}
                className="w-full bg-primary text-on-primary font-headline font-bold uppercase py-3 border-2 border-primary shadow-[4px_4px_0px_0px_rgba(26,26,26,1)] hover:bg-secondary hover:border-secondary transition-colors disabled:opacity-50"
              >
                {loading ? t('settings.verifying') : t('settings.verifyAndEnable')}
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

function TwoFADisableModal({ onClose, onDisabled }) {
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleDisable = async () => {
    setLoading(true);
    setError('');
    try {
      const csrfRes = await fetch('/api/csrf-token', { credentials: 'include' });
      const { csrfToken } = await csrfRes.json();

      const res = await fetch('/api/auth/2fa/disable', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
        body: JSON.stringify({ password }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || t('settings.saveError'));

      onDisabled();
      onClose();
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 overflow-y-auto">
      <div className="bg-surface border-4 border-primary shadow-[8px_8px_0px_0px_rgba(26,26,26,1)] w-full max-w-md my-8">
        <div className="bg-error-container text-error p-4 border-b-4 border-error flex justify-between items-center">
          <h3 className="font-headline font-black text-lg uppercase">{t('settings.disable2FA')}</h3>
          <button onClick={onClose} className="text-error hover:opacity-75">
            <span className="material-symbols-outlined">close</span>
          </button>
        </div>

        <div className="p-6 space-y-4">
          {error && (
            <div className="bg-error-container border-2 border-error p-3 font-label font-bold uppercase text-sm text-error">
              {error}
            </div>
          )}
          <p className="font-body text-sm text-on-surface-variant">
            {t('settings.disable2FADesc')}
          </p>
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="w-full bg-background border-2 border-primary p-3 font-body font-bold text-primary focus:outline-none focus:border-secondary"
            placeholder={t('settings.passwordPlaceholder')}
            autoFocus
          />
          <div className="flex gap-3">
            <button
              onClick={onClose}
              className="flex-1 bg-surface text-primary font-headline font-bold uppercase py-3 border-2 border-primary shadow-[4px_4px_0px_0px_rgba(26,26,26,1)] hover:bg-primary hover:text-on-primary transition-colors"
            >
              {t('admin.cancel')}
            </button>
            <button
              onClick={handleDisable}
              disabled={loading || !password}
              className="flex-1 bg-error text-on-error font-headline font-bold uppercase py-3 border-2 border-primary shadow-[4px_4px_0px_0px_rgba(26,26,26,1)] hover:opacity-75 transition-colors disabled:opacity-50"
            >
              {loading ? t('settings.disabling') : t('settings.disable')}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default function Settings({ user }) {
  const { t, lang, setLang } = useI18n();
  const { dark, toggle: toggleDark } = useTheme();

  const [settings, setSettings] = useState({
    displayName: user?.username || 'Admin',
    email: '',
    role: user?.role || 'viewer',
    defaultZone: 'Sorrento',
    currency: 'EUR',
    notifications: true,
    emailAlerts: true,
    lowStockAlerts: true,
    priceChangeAlerts: true,
    compactView: false,
    autoRefresh: true,
    refreshInterval: '30',
  });

  const [twoFAEnabled, setTwoFAEnabled] = useState(false);
  const [showTwoFAModal, setShowTwoFAModal] = useState(false);
  const [showTwoFADisableModal, setShowTwoFADisableModal] = useState(false);

  const [saved, setSaved] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState(null);
  const [regenerating, setRegenerating] = useState(false);
  const [newApiKey, setNewApiKey] = useState(null);
  const [validating, setValidating] = useState(false);
  const [validationResult, setValidationResult] = useState(null);
  const [purging, setPurging] = useState(false);
  const [purgeResult, setPurgeResult] = useState(null);

  useEffect(() => {
    if (user) {
      fetch('/api/admin/me', { credentials: 'include' })
        .then(r => r.ok ? r.json() : null)
        .then(data => {
          if (data?.user) {
            setSettings(prev => ({
              ...prev,
              displayName: data.user.displayName || data.user.username || prev.displayName,
              email: data.user.email || '',
              role: data.user.role || prev.role,
            }));
          }
        })
        .catch(() => {});

      fetch('/api/auth/2fa/status', { credentials: 'include' })
        .then(r => r.ok ? r.json() : null)
        .then(data => {
          if (data) setTwoFAEnabled(data.enabled);
        })
        .catch(() => {});
    }
  }, [user]);

  useEffect(() => {
    setSettings((prev) => ({
      ...prev,
      language: lang,
      darkMode: dark,
    }));
  }, [lang, dark]);

  const handleChange = (key, value) => {
    if (key === 'language') {
      setLang(value);
      return;
    }
    if (key === 'darkMode') {
      toggleDark();
      return;
    }
    setSettings((prev) => ({ ...prev, [key]: value }));
    setSaved(false);
  };

  const handleSave = async () => {
    if (!settings.displayName.trim()) {
      setSaveError(t('settings.displayNameRequired'));
      return;
    }
    setSaving(true);
    setSaveError(null);
    try {
      const csrfRes = await fetch('/api/csrf-token', { credentials: 'include' });
      const { csrfToken } = await csrfRes.json();

      const res = await fetch('/api/admin/profile', {
        method: 'PUT',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
        body: JSON.stringify({
          displayName: settings.displayName.trim(),
          email: settings.email.trim(),
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || t('settings.saveError'));
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
    } catch (err) {
      setSaveError(err.message);
    } finally {
      setSaving(false);
    }
  };

  const handleReset = () => {
    if (user) {
      fetch('/api/admin/me', { credentials: 'include' })
        .then(r => r.ok ? r.json() : null)
        .then(data => {
          if (data?.user) {
            setSettings({
              displayName: data.user.displayName || data.user.username || 'Admin',
              email: data.user.email || '',
              role: data.user.role || 'viewer',
              defaultZone: 'Sorrento',
              currency: 'EUR',
              notifications: true,
              emailAlerts: true,
              lowStockAlerts: true,
              priceChangeAlerts: true,
              compactView: false,
              autoRefresh: true,
              refreshInterval: '30',
            });
          }
        })
        .catch(() => {});
    }
    setSaved(false);
    setSaveError(null);
  };

  const handleRegenerateKey = async () => {
    setRegenerating(true);
    setNewApiKey(null);
    try {
      const csrfRes = await fetch('/api/csrf-token', { credentials: 'include' });
      const { csrfToken } = await csrfRes.json();
      const res = await fetch('/api/admin/regenerate-key', {
        method: 'POST', credentials: 'include',
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || t('settings.regenerationError'));
      setNewApiKey(data.apiKey);
    } catch (err) {
      setSaveError(err.message);
    } finally {
      setRegenerating(false);
    }
  };

  const handleValidateJson = async () => {
    setValidating(true);
    setValidationResult(null);
    try {
      const csrfRes = await fetch('/api/csrf-token', { credentials: 'include' });
      const { csrfToken } = await csrfRes.json();
      const res = await fetch('/api/admin/validate-json', {
        method: 'POST', credentials: 'include',
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || t('settings.validationError'));
      setValidationResult(data);
    } catch (err) {
      setSaveError(err.message);
    } finally {
      setValidating(false);
    }
  };

  const handleExportData = async () => {
    try {
      const res = await fetch('/api/admin/export-data', { credentials: 'include' });
      if (!res.ok) throw new Error(t('settings.exportError'));
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url; a.download = 'pizza-data-export.json'; a.click();
      URL.revokeObjectURL(url);
    } catch (err) {
      setSaveError(err.message);
    }
  };

  const handlePurgeCache = async () => {
    setPurging(true);
    setPurgeResult(null);
    try {
      const csrfRes = await fetch('/api/csrf-token', { credentials: 'include' });
      const { csrfToken } = await csrfRes.json();
      const res = await fetch('/api/admin/purge-cache', {
        method: 'POST', credentials: 'include',
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || t('settings.purgeError'));
      setPurgeResult({ success: true, message: data.message });
      setTimeout(() => setPurgeResult(null), 3000);
    } catch (err) {
      setPurgeResult({ success: false, message: err.message });
      setTimeout(() => setPurgeResult(null), 3000);
    } finally {
      setPurging(false);
    }
  };

  return (
    <div className="p-6 md:p-12 max-w-5xl mx-auto">
      <header className="mb-12 border-b-4 border-primary pb-6">
        <h1 className="text-5xl md:text-7xl font-black font-headline tracking-tighter uppercase mb-4 text-primary">
          {t('settings.title')}
        </h1>
        <p className="text-xl font-bold font-body max-w-2xl text-on-surface-variant">
          {t('settings.subtitle')}
        </p>
      </header>

      <section className="mb-8">
        <div className="flex items-center gap-4 border-b-4 border-primary pb-4 mb-6">
          <span className="material-symbols-outlined text-3xl text-primary">person</span>
          <h2 className="text-3xl font-headline font-black uppercase">{t('settings.profile')}</h2>
        </div>
        <div className="bg-surface-bright border-4 border-primary shadow-[4px_4px_0px_0px_rgba(26,26,26,1)] p-6 md:p-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-black font-headline uppercase tracking-widest mb-2 text-primary">
                {t('settings.displayName')}
              </label>
              <input
                type="text"
                className="w-full bg-background border-2 border-primary p-3 font-body font-bold text-primary focus:ring-0 focus:border-secondary"
                value={settings.displayName}
                onChange={(e) => handleChange('displayName', e.target.value)}
              />
            </div>
            <div>
              <label className="block text-sm font-black font-headline uppercase tracking-widest mb-2 text-primary">
                {t('settings.email')}
              </label>
              <input
                type="email"
                className="w-full bg-background border-2 border-primary p-3 font-body font-bold text-primary focus:ring-0 focus:border-secondary"
                value={settings.email}
                onChange={(e) => handleChange('email', e.target.value)}
                placeholder={t('settings.emailPlaceholder')}
              />
            </div>
            <div>
              <label className="block text-sm font-black font-headline uppercase tracking-widest mb-2 text-primary">
                {t('settings.role')}
              </label>
              <div className="w-full bg-background border-2 border-primary p-3 font-body font-bold text-primary uppercase flex items-center gap-2">
                <span className="material-symbols-outlined text-sm text-tertiary">shield</span>
                {settings.role === 'admin' ? t('settings.roleAdmin') : settings.role === 'editor' ? t('settings.roleEditor') : t('settings.roleViewer')}
              </div>
            </div>
            <div>
              <label className="block text-sm font-black font-headline uppercase tracking-widest mb-2 text-primary">
                {t('settings.defaultZone')}
              </label>
              <select
                className="w-full bg-background border-2 border-primary p-3 font-body font-bold text-primary focus:ring-0 focus:border-secondary cursor-pointer"
                value={settings.defaultZone}
                onChange={(e) => handleChange('defaultZone', e.target.value)}
              >
                {ZONES.map((z) => (
                  <option key={z} value={z}>
                    {z}
                  </option>
                ))}
              </select>
            </div>
          </div>
        </div>
      </section>

      <section className="mb-8">
        <div className="flex items-center gap-4 border-b-4 border-primary pb-4 mb-6">
          <span className="material-symbols-outlined text-3xl text-primary">language</span>
          <h2 className="text-3xl font-headline font-black uppercase">{t('settings.regional')}</h2>
        </div>
        <div className="bg-surface-bright border-4 border-primary shadow-[4px_4px_0px_0px_rgba(26,26,26,1)] p-6 md:p-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-black font-headline uppercase tracking-widest mb-2 text-primary">
                {t('settings.currency')}
              </label>
              <select
                className="w-full bg-background border-2 border-primary p-3 font-body font-bold text-primary focus:ring-0 focus:border-secondary cursor-pointer"
                value={settings.currency}
                onChange={(e) => handleChange('currency', e.target.value)}
              >
                <option value="EUR">EUR - Euro</option>
                <option value="USD">USD - US Dollar</option>
                <option value="GBP">GBP - British Pound</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-black font-headline uppercase tracking-widest mb-2 text-primary">
                {t('settings.language')}
              </label>
              <select
                className="w-full bg-background border-2 border-primary p-3 font-body font-bold text-primary focus:ring-0 focus:border-secondary cursor-pointer"
                value={lang}
                onChange={(e) => handleChange('language', e.target.value)}
              >
                <option value="it">Italiano</option>
                <option value="en">English</option>
              </select>
            </div>
          </div>
        </div>
      </section>

      <section className="mb-8">
        <div className="flex items-center gap-4 border-b-4 border-primary pb-4 mb-6">
          <span className="material-symbols-outlined text-3xl text-primary">notifications</span>
          <h2 className="text-3xl font-headline font-black uppercase">{t('settings.notifications')}</h2>
        </div>
        <div className="bg-surface-bright border-4 border-primary shadow-[4px_4px_0px_0px_rgba(26,26,26,1)] p-6 md:p-8">
          <div className="flex flex-col gap-6">
            <div className="flex justify-between items-center">
              <div>
                <h4 className="font-headline font-bold uppercase">{t('settings.pushNotifications')}</h4>
                <p className="font-body text-sm text-on-surface-variant">{t('settings.pushNotificationsDesc')}</p>
              </div>
              <Toggle value={settings.notifications} onChange={(v) => handleChange('notifications', v)} />
            </div>
            <div className="border-t-2 border-outline-variant" />
            <div className="flex justify-between items-center">
              <div>
                <h4 className="font-headline font-bold uppercase">{t('settings.emailAlerts')}</h4>
                <p className="font-body text-sm text-on-surface-variant">{t('settings.emailAlertsDesc')}</p>
              </div>
              <Toggle value={settings.emailAlerts} onChange={(v) => handleChange('emailAlerts', v)} />
            </div>
            <div className="border-t-2 border-outline-variant" />
            <div className="flex justify-between items-center">
              <div>
                <h4 className="font-headline font-bold uppercase">{t('settings.lowStockAlerts')}</h4>
                <p className="font-body text-sm text-on-surface-variant">{t('settings.lowStockAlertsDesc')}</p>
              </div>
              <Toggle value={settings.lowStockAlerts} onChange={(v) => handleChange('lowStockAlerts', v)} />
            </div>
            <div className="border-t-2 border-outline-variant" />
            <div className="flex justify-between items-center">
              <div>
                <h4 className="font-headline font-bold uppercase">{t('settings.priceChangeAlerts')}</h4>
                <p className="font-body text-sm text-on-surface-variant">{t('settings.priceChangeAlertsDesc')}</p>
              </div>
              <Toggle value={settings.priceChangeAlerts} onChange={(v) => handleChange('priceChangeAlerts', v)} />
            </div>
          </div>
        </div>
      </section>

      <section className="mb-8">
        <div className="flex items-center gap-4 border-b-4 border-primary pb-4 mb-6">
          <span className="material-symbols-outlined text-3xl text-primary">palette</span>
          <h2 className="text-3xl font-headline font-black uppercase">{t('settings.display')}</h2>
        </div>
        <div className="bg-surface-bright border-4 border-primary shadow-[4px_4px_0px_0px_rgba(26,26,26,1)] p-6 md:p-8">
          <div className="flex flex-col gap-6">
            <div className="flex justify-between items-center">
              <div>
                <h4 className="font-headline font-bold uppercase">{t('settings.darkMode')}</h4>
                <p className="font-body text-sm text-on-surface-variant">{t('settings.darkModeDesc')}</p>
              </div>
              <Toggle value={dark} onChange={() => handleChange('darkMode', !dark)} />
            </div>
            <div className="border-t-2 border-outline-variant" />
            <div className="flex justify-between items-center">
              <div>
                <h4 className="font-headline font-bold uppercase">{t('settings.compactView')}</h4>
                <p className="font-body text-sm text-on-surface-variant">{t('settings.compactViewDesc')}</p>
              </div>
              <Toggle value={settings.compactView} onChange={(v) => handleChange('compactView', v)} />
            </div>
            <div className="border-t-2 border-outline-variant" />
            <div className="flex justify-between items-center">
              <div>
                <h4 className="font-headline font-bold uppercase">{t('settings.autoRefresh')}</h4>
                <p className="font-body text-sm text-on-surface-variant">{t('settings.autoRefreshDesc')}</p>
              </div>
              <Toggle value={settings.autoRefresh} onChange={(v) => handleChange('autoRefresh', v)} />
            </div>
            {settings.autoRefresh && (
              <>
                <div className="border-t-2 border-outline-variant" />
                <div className="flex justify-between items-center">
                  <div>
                    <h4 className="font-headline font-bold uppercase">{t('settings.refreshInterval')}</h4>
                    <p className="font-body text-sm text-on-surface-variant">{t('settings.refreshIntervalDesc')}</p>
                  </div>
                  <select
                    className="bg-background border-2 border-primary p-2 font-body font-bold text-primary focus:ring-0 focus:border-secondary cursor-pointer"
                    value={settings.refreshInterval}
                    onChange={(e) => handleChange('refreshInterval', e.target.value)}
                  >
                    <option value="15">15s</option>
                    <option value="30">30s</option>
                    <option value="60">60s</option>
                    <option value="120">120s</option>
                  </select>
                </div>
              </>
            )}
          </div>
        </div>
      </section>

      <section className="mb-8">
        <div className="flex items-center gap-4 border-b-4 border-primary pb-4 mb-6">
          <span className="material-symbols-outlined text-3xl text-primary">shield</span>
          <h2 className="text-3xl font-headline font-black uppercase">{t('settings.security')}</h2>
        </div>
        <div className="bg-surface-bright border-4 border-primary shadow-[4px_4px_0px_0px_rgba(26,26,26,1)] p-6 md:p-8">
          <div className="flex flex-col gap-6">
            <div className="flex justify-between items-center">
              <div>
                <h4 className="font-headline font-bold uppercase">{t('settings.twoFactor')}</h4>
                <p className="font-body text-sm text-on-surface-variant">{t('settings.twoFactorDesc')}</p>
              </div>
              {twoFAEnabled ? (
                <button
                  onClick={() => setShowTwoFADisableModal(true)}
                  className="bg-error text-on-error font-label font-bold uppercase px-4 py-2 border-2 border-primary shadow-[2px_2px_0px_0px_rgba(26,26,26,1)] hover:opacity-75 transition-colors"
                >
                  {t('settings.disable')}
                </button>
              ) : (
                <button
                  onClick={() => setShowTwoFAModal(true)}
                  className="bg-primary text-on-primary font-label font-bold uppercase px-4 py-2 border-2 border-primary shadow-[2px_2px_0px_0px_rgba(26,26,26,1)] hover:bg-secondary hover:border-secondary transition-colors"
                >
                  {t('settings.enable2FA')}
                </button>
              )}
            </div>
            <div className="border-t-2 border-outline-variant" />
            <div className="flex justify-between items-center">
              <div>
                <h4 className="font-headline font-bold uppercase">{t('settings.apiAccessKey')}</h4>
                <p className="font-body text-sm text-on-surface-variant">{t('settings.apiAccessKeyDesc')}</p>
              </div>
              <button onClick={handleRegenerateKey} disabled={regenerating}
                className="bg-surface text-primary font-label font-bold uppercase px-4 py-2 border-2 border-primary shadow-[2px_2px_0px_0px_rgba(26,26,26,1)] hover:bg-primary hover:text-on-primary transition-colors disabled:opacity-50">
                {regenerating ? '...' : t('settings.regenerate')}
              </button>
              {newApiKey && (
                <div className="mt-2 bg-background border-2 border-primary p-3 flex items-center gap-2">
                  <code className="font-mono text-sm break-all text-primary flex-1">{newApiKey}</code>
                  <button onClick={() => { navigator.clipboard.writeText(newApiKey); setNewApiKey(null); }}
                    className="bg-primary text-on-primary font-label font-bold uppercase px-3 py-1 border-2 border-primary text-xs">{t('settings.copy')}</button>
                </div>
              )}
            </div>
            <div className="border-t-2 border-outline-variant" />
            <div className="flex justify-between items-center">
              <div>
                <h4 className="font-headline font-bold uppercase">{t('settings.corsPolicy')}</h4>
                <p className="font-body text-sm text-on-surface-variant">{t('settings.corsPolicyDesc')}</p>
              </div>
              <span className="bg-primary-container text-on-primary-container font-label font-bold uppercase px-3 py-1 border-2 border-primary text-sm">
                {t('settings.active')}
              </span>
            </div>
          </div>
        </div>
      </section>

      {showTwoFAModal && (
        <TwoFAModal
          onClose={() => setShowTwoFAModal(false)}
          onEnabled={() => setTwoFAEnabled(true)}
        />
      )}

      {showTwoFADisableModal && (
        <TwoFADisableModal
          onClose={() => setShowTwoFADisableModal(false)}
          onDisabled={() => setTwoFAEnabled(false)}
        />
      )}

      <section className="mb-8">
        <div className="flex items-center gap-4 border-b-4 border-primary pb-4 mb-6">
          <span className="material-symbols-outlined text-3xl text-primary">database</span>
          <h2 className="text-3xl font-headline font-black uppercase">{t('settings.data')}</h2>
        </div>
        <div className="bg-surface-bright border-4 border-primary shadow-[4px_4px_0px_0px_rgba(26,26,26,1)] p-6 md:p-8">
          <div className="flex flex-col gap-6">
            <div className="flex justify-between items-center">
              <div>
                <h4 className="font-headline font-bold uppercase">{t('settings.validateJson')}</h4>
                <p className="font-body text-sm text-on-surface-variant">{t('settings.validateJsonDesc')}</p>
              </div>
              <button onClick={handleValidateJson} disabled={validating}
                className="bg-primary text-on-primary font-label font-bold uppercase px-4 py-2 border-2 border-primary shadow-[2px_2px_0px_0px_rgba(26,26,26,1)] hover:bg-surface hover:text-primary transition-colors disabled:opacity-50">
                {validating ? '...' : t('settings.validate')}
              </button>
              {validationResult && (
                <div className={`mt-2 p-3 border-2 font-label text-sm ${validationResult.valid ? 'bg-tertiary-container border-tertiary' : 'bg-error-container border-error'}`}>
                  {validationResult.valid ? t('settings.jsonValid') : t('settings.jsonErrors', { count: validationResult.errors.length })}
                  {!validationResult.valid && (
                    <ul className="mt-1 list-disc list-inside">
                      {validationResult.errors.slice(0, 10).map((e, i) => <li key={i}>{e}</li>)}
                      {validationResult.errors.length > 10 && <li>{t('settings.moreErrors', { count: validationResult.errors.length - 10 })}</li>}
                    </ul>
                  )}
                </div>
              )}
            </div>
            <div className="border-t-2 border-outline-variant" />
            <div className="flex justify-between items-center">
              <div>
                <h4 className="font-headline font-bold uppercase">{t('settings.exportAllData')}</h4>
                <p className="font-body text-sm text-on-surface-variant">{t('settings.exportAllDataDesc')}</p>
              </div>
              <button onClick={handleExportData}
                className="bg-surface text-primary font-label font-bold uppercase px-4 py-2 border-2 border-primary shadow-[2px_2px_0px_0px_rgba(26,26,26,1)] hover:bg-primary hover:text-on-primary transition-colors">
                {t('settings.export')}
              </button>
            </div>
            <div className="border-t-2 border-outline-variant" />
            <div className="flex justify-between items-center">
              <div>
                <h4 className="font-headline font-bold uppercase text-secondary">{t('settings.purgeCache')}</h4>
                <p className="font-body text-sm text-on-surface-variant">{t('settings.purgeCacheDesc')}</p>
              </div>
              <button onClick={handlePurgeCache} disabled={purging}
                className="bg-secondary text-on-error font-label font-bold uppercase px-4 py-2 border-2 border-primary shadow-[2px_2px_0px_0px_rgba(26,26,26,1)] hover:bg-primary hover:text-on-primary transition-colors disabled:opacity-50">
                {purging ? '...' : t('settings.purge')}
              </button>
              {purgeResult && (
                <div className={`mt-2 p-3 border-2 font-label text-sm ${purgeResult.success ? 'bg-tertiary-container border-tertiary' : 'bg-error-container border-error'}`}>
                  {purgeResult.success ? t('settings.cachePurged') : `❌ ${purgeResult.message}`}
                </div>
              )}
            </div>
          </div>
        </div>
      </section>

      <div className="sticky bottom-0 bg-background border-t-4 border-primary p-4 flex justify-between items-center z-30">
        <button
          onClick={handleReset}
          className="bg-surface text-primary font-headline font-bold uppercase px-6 py-3 border-2 border-primary shadow-[4px_4px_0px_0px_rgba(26,26,26,1)] hover:bg-error-container hover:text-on-error-container transition-colors"
        >
          {t('settings.resetDefaults')}
        </button>
        <div className="flex items-center gap-4">
          {saveError && (
            <span className="font-label font-bold uppercase text-error flex items-center gap-2">
              <span className="material-symbols-outlined">error</span>
              {saveError}
            </span>
          )}
          {saved && (
            <span className="font-label font-bold uppercase text-primary flex items-center gap-2">
              <span className="material-symbols-outlined text-primary-fixed-dim" style={{ fontVariationSettings: "'FILL' 1" }}>
                check_circle
              </span>
              {t('settings.saved')}
            </span>
          )}
          <button
            onClick={handleSave}
            disabled={saving}
            className="bg-primary text-on-primary font-headline font-bold uppercase px-8 py-3 border-2 border-primary shadow-[4px_4px_0px_0px_rgba(26,26,26,1)] hover:bg-primary-container hover:text-on-primary-container transition-colors active:translate-x-1 active:translate-y-1 active:shadow-none disabled:opacity-50"
          >
            {saving ? t('admin.saving') : t('settings.saveSettings')}
          </button>
        </div>
      </div>
    </div>
  );
}

const API_BASE = globalThis.process?.env?.VITE_API_BASE || '';

let authCache = null;
let authCacheTime = 0;
const CACHE_TTL = 30000;

export async function checkAuth() {
  const now = Date.now();
  if (authCache && now - authCacheTime < CACHE_TTL) return authCache;

  try {
    const res = await fetch(`${API_BASE}/api/admin/me`, { credentials: 'include' });
    if (!res.ok) {
      authCache = null;
      return null;
    }
    const data = await res.json();
    authCache = data.user;
    authCacheTime = now;
    return data.user;
  } catch {
    authCache = null;
    return null;
  }
}

export async function logout() {
  try {
    const csrfRes = await fetch(`${API_BASE}/api/csrf-token`, { credentials: 'include' });
    const { csrfToken } = await csrfRes.json();
    await fetch(`${API_BASE}/api/auth/logout`, {
      method: 'POST',
      credentials: 'include',
      headers: { 'X-CSRF-Token': csrfToken },
    });
  } catch {}
  authCache = null;
}

export function clearAuthCache() {
  authCache = null;
  authCacheTime = 0;
}

import { createContext, useContext, useState, useCallback, useEffect } from 'react';

const ThemeContext = createContext();

const STORAGE_KEY = 'pizza-peninsula-theme';

export function ThemeProvider({ children }) {
  const [dark, setDarkState] = useState(() => {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored !== null) return stored === 'true';
    return window.matchMedia('(prefers-color-scheme: dark)').matches;
  });

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', dark ? 'dark' : 'light');
    localStorage.setItem(STORAGE_KEY, String(dark));
  }, [dark]);

  const toggle = useCallback(() => setDarkState((prev) => !prev), []);

  return (
    <ThemeContext.Provider value={{ dark, toggle, setDark: setDarkState }}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme() {
  const ctx = useContext(ThemeContext);
  if (!ctx) throw new Error('useTheme must be used within ThemeProvider');
  return ctx;
}
